//! Independent fixtures generated by ntfs-3g, without mounting or privilege.
use disk_capture::Volume;
use std::{fs, process::Command, sync::Arc};
use virtdisk::RawDisk;
fn digest(path: &std::path::Path) -> Vec<u8> {
    use sha2::{Digest, Sha256};
    use std::io::Read;
    let mut file = fs::File::open(path).unwrap();
    let mut hash = Sha256::new();
    let mut buffer = [0; 65536];
    loop {
        let count = file.read(&mut buffer).unwrap();
        if count == 0 {
            break;
        }
        hash.update(&buffer[..count]);
    }
    hash.finalize().to_vec()
}

#[test]
#[ignore = "requires frozen Windows-created QCOW2 hard-link alias fixture; set WINDOWS_NTFS_HARDLINK_ALIAS_QCOW2"]
fn assigns_dos_alias_only_to_win32_link_in_actual_windows_fixture() {
    use partmgr::PartitionTable;
    use virtdisk::Qcow2;
    let fixture = std::env::var_os("WINDOWS_NTFS_HARDLINK_ALIAS_QCOW2")
        .expect("WINDOWS_NTFS_HARDLINK_ALIAS_QCOW2");
    let fixture = std::path::PathBuf::from(fixture);
    let before = digest(&fixture);
    let table =
        PartitionTable::read(Arc::new(Qcow2::open_chain(&fixture, &[]).unwrap()), 512).unwrap();
    let volume = Volume::open(Arc::new(table.select(1).unwrap())).unwrap();
    let manifest = volume.capture_manifest().unwrap();
    let mut paths = vec![String::new(); manifest.nodes.len()];
    for (index, node) in manifest.nodes.iter().enumerate().skip(1) {
        paths[index] = format!(
            "{}/{}",
            paths[node.parent.unwrap()],
            String::from_utf16(&node.name).unwrap()
        );
    }
    let root = "/QCOW2-AliasCreation-76a27ca0c9ee4bc89560a02413899dec";
    for (relative, expected) in [
        ("order0/same/FaceProcessor.dll", "FACEPR~1.DLL"),
        ("order0/same/FaceProcessorCore.dll", ""),
        ("order1/same/FaceProcessor.dll", ""),
        ("order1/same/FaceProcessorCore.dll", "FACEPR~1.DLL"),
        ("order2/same/FaceProcessor.dll", ""),
        ("order2/same/FaceProcessorCore.dll", ""),
        ("order2/other/RenamedFaceProcessorExtra.dll", "RENAME~1.DLL"),
    ] {
        let index = paths
            .iter()
            .position(|path| path == &format!("{root}/{relative}"))
            .unwrap();
        assert_eq!(
            manifest.nodes[index].short_name,
            expected.encode_utf16().collect::<Vec<_>>(),
            "{relative}"
        );
    }
    let filtered = volume
        .capture_manifest_with_filter(|path| {
            String::from_utf16_lossy(path.last().unwrap()) != "FaceProcessor.dll"
        })
        .unwrap();
    let mut filtered_paths = vec![String::new(); filtered.nodes.len()];
    for (index, node) in filtered.nodes.iter().enumerate().skip(1) {
        filtered_paths[index] = format!(
            "{}/{}",
            filtered_paths[node.parent.unwrap()],
            String::from_utf16(&node.name).unwrap()
        );
    }
    let index = filtered_paths
        .iter()
        .position(|path| path == &format!("{root}/order0/same/FaceProcessorCore.dll"))
        .unwrap();
    assert!(filtered.nodes[index].short_name.is_empty());
    assert_eq!(digest(&fixture), before);
}

fn command(program: &str, args: &[&str]) {
    let output = Command::new(program).args(args).output().unwrap();
    assert!(
        output.status.success(),
        "{program}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}
#[test]
#[ignore = "requires mkntfs and ntfscp on PATH; nix-shell -p ntfs3g --run 'cargo test -p windows-ntfs --test ntfs3g -- --ignored'"]
fn captures_independently_formatted_ntfs_and_ads_without_mounting() {
    let directory = tempfile::tempdir().unwrap();
    let image = directory.path().join("volume.ntfs");
    fs::File::create(&image)
        .unwrap()
        .set_len(32 * 1024 * 1024)
        .unwrap();
    let image = image.to_str().unwrap();
    command("mkntfs", &["-F", "-Q", "-c", "512", image]);
    let resident = directory.path().join("resident");
    fs::write(&resident, b"resident data\0").unwrap();
    let large = directory.path().join("large");
    let contents = (0..65539).map(|i| (i * 31) as u8).collect::<Vec<_>>();
    fs::write(&large, &contents).unwrap();
    let ads = directory.path().join("ads");
    fs::write(&ads, b"alternate stream").unwrap();
    command("ntfscp", &[image, resident.to_str().unwrap(), "/small.txt"]);
    command("ntfscp", &[image, large.to_str().unwrap(), "/large.dat"]);
    command(
        "ntfscp",
        &["-N", "payload", image, ads.to_str().unwrap(), "/small.txt"],
    );
    let volume = Volume::open(Arc::new(RawDisk::open(image).unwrap())).unwrap();
    let manifest = volume.capture_manifest().unwrap();
    assert!(
        manifest
            .nodes
            .iter()
            .any(|n| n.name == "small.txt".encode_utf16().collect::<Vec<_>>())
    );
    let path = vec!["LARGE.DAT".encode_utf16().collect()];
    let stream = volume.read_file(&path, &[]).unwrap();
    let mut output = vec![0; contents.len()];
    stream.read_exact_at(0, &mut output).unwrap();
    assert_eq!(output, contents);
    let path = vec!["small.txt".encode_utf16().collect()];
    let stream = volume
        .read_file(&path, &"PAYLOAD".encode_utf16().collect::<Vec<_>>())
        .unwrap();
    let mut output = vec![0; stream.len() as usize];
    stream.read_exact_at(0, &mut output).unwrap();
    assert_eq!(output, b"alternate stream");
    let filtered = volume
        .capture_manifest_with_filter(|path| {
            path[0] != "large.dat".encode_utf16().collect::<Vec<_>>()
        })
        .unwrap();
    assert!(
        !filtered
            .nodes
            .iter()
            .any(|n| n.name == "large.dat".encode_utf16().collect::<Vec<_>>())
    );
    assert_eq!(filtered.nodes[0].parent, None);
    let error = volume
        .capture_manifest_with_fallible_filter(|_| {
            Err(std::io::Error::new(
                std::io::ErrorKind::Interrupted,
                "cancelled traversal",
            ))
        })
        .err()
        .unwrap();
    assert_eq!(error.kind(), std::io::ErrorKind::Interrupted);
    assert!(volume.capture_manifest().is_ok());
    drop(volume);
    fs::write(&resident, b"hibr").unwrap();
    command(
        "ntfscp",
        &[image, resident.to_str().unwrap(), "/hiberfil.sys"],
    );
    let volume = Volume::open(Arc::new(RawDisk::open(image).unwrap())).unwrap();
    let error = volume
        .capture_manifest_with_filter(|_| false)
        .err()
        .expect("hibernation check must precede exclusions");
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(error.to_string().contains("hibernated or fast-startup"));
}

#[test]
#[ignore = "requires retained Windows-created NTFS fixture; set WINDOWS_NTFS_CASE_FIXTURE"]
fn rejects_empty_case_sensitive_directory_created_by_windows() {
    let fixture = std::env::var_os("WINDOWS_NTFS_CASE_FIXTURE").expect("WINDOWS_NTFS_CASE_FIXTURE");
    let volume = Volume::open(Arc::new(RawDisk::open(&fixture).unwrap())).unwrap();
    let error = volume
        .capture_manifest()
        .err()
        .expect("must reject case directory even when empty");
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(
        error
            .to_string()
            .contains("case-sensitive NTFS directories")
    );
    let manifest = volume
        .capture_manifest_with_filter(|path| path[0] != "case".encode_utf16().collect::<Vec<_>>())
        .unwrap();
    let control = manifest
        .nodes
        .iter()
        .find(|n| n.name == "control".encode_utf16().collect::<Vec<_>>())
        .unwrap();
    assert_eq!(control.attributes, 0x10);
}

#[test]
#[ignore = "requires retained Windows-created NTFS fixture; set WINDOWS_NTFS_CASE_FIXTURE"]
fn rejects_dirty_and_unknown_volume_flags_before_metadata_capture() {
    use std::io::{Read, Seek, SeekFrom, Write};
    let original =
        std::env::var_os("WINDOWS_NTFS_CASE_FIXTURE").expect("WINDOWS_NTFS_CASE_FIXTURE");
    let directory = tempfile::tempdir().unwrap();
    let copy = directory.path().join("dirty.ntfs");
    fs::copy(original, &copy).unwrap();
    let mut file = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(&copy)
        .unwrap();
    let mut boot = [0; 512];
    file.read_exact(&mut boot).unwrap();
    let sector = u16::from_le_bytes(boot[11..13].try_into().unwrap()) as u64;
    let cluster = sector * u64::from(boot[13]);
    let mft = u64::from_le_bytes(boot[48..56].try_into().unwrap()) * cluster;
    let exponent = boot[64] as i8;
    let record = if exponent < 0 {
        1u64 << (-exponent as u32)
    } else {
        cluster * exponent as u64
    };
    let location = mft + 3 * record;
    file.seek(SeekFrom::Start(location)).unwrap();
    let mut data = vec![0; record as usize];
    file.read_exact(&mut data).unwrap();
    let mut offset = u16::from_le_bytes(data[20..22].try_into().unwrap()) as usize;
    let target = loop {
        let ty = u32::from_le_bytes(data[offset..offset + 4].try_into().unwrap());
        assert_ne!(ty, u32::MAX);
        if ty == 0x70 {
            let value =
                u16::from_le_bytes(data[offset + 20..offset + 22].try_into().unwrap()) as usize;
            break location + (offset + value + 10) as u64;
        }
        offset += u32::from_le_bytes(data[offset + 4..offset + 8].try_into().unwrap()) as usize;
    };
    for flag in [1u16, 0x100] {
        file.seek(SeekFrom::Start(target)).unwrap();
        file.write_all(&flag.to_le_bytes()).unwrap();
        file.sync_all().unwrap();
        let error = Volume::open(Arc::new(RawDisk::open(&copy).unwrap()))
            .err()
            .expect("must reject unclean/unknown state");
        assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
        assert!(error.to_string().contains("recovery or has unknown state"));
    }
}

#[test]
#[ignore = "requires retained Windows-created NTFS fixture; set WINDOWS_NTFS_CASE_FIXTURE"]
fn rejects_inconsistent_secure_index_before_capturing_acls() {
    use std::io::{Read, Seek, SeekFrom, Write};
    let original =
        std::env::var_os("WINDOWS_NTFS_CASE_FIXTURE").expect("WINDOWS_NTFS_CASE_FIXTURE");
    let directory = tempfile::tempdir().unwrap();
    let copy = directory.path().join("bad-security.ntfs");
    fs::copy(original, &copy).unwrap();
    let mut file = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(&copy)
        .unwrap();
    let mut boot = [0; 512];
    file.read_exact(&mut boot).unwrap();
    let sector = u16::from_le_bytes(boot[11..13].try_into().unwrap()) as u64;
    let cluster = sector * u64::from(boot[13]);
    let mft = u64::from_le_bytes(boot[48..56].try_into().unwrap()) * cluster;
    let exponent = boot[64] as i8;
    let record = if exponent < 0 {
        1u64 << (-exponent as u32)
    } else {
        cluster * exponent as u64
    };
    let location = mft + 9 * record;
    file.seek(SeekFrom::Start(location)).unwrap();
    let mut data = vec![0; record as usize];
    file.read_exact(&mut data).unwrap();
    let mut offset = u16::from_le_bytes(data[20..22].try_into().unwrap()) as usize;
    let target = loop {
        let ty = u32::from_le_bytes(data[offset..offset + 4].try_into().unwrap());
        assert_ne!(ty, u32::MAX);
        let name_offset =
            u16::from_le_bytes(data[offset + 10..offset + 12].try_into().unwrap()) as usize;
        let name_length = usize::from(data[offset + 9]) * 2;
        let name = data[offset + name_offset..offset + name_offset + name_length]
            .chunks_exact(2)
            .map(|b| u16::from_le_bytes([b[0], b[1]]))
            .collect::<Vec<_>>();
        if ty == 0x90 && name == "$SII".encode_utf16().collect::<Vec<_>>() {
            assert_eq!(data[offset + 8], 0);
            let value =
                u16::from_le_bytes(data[offset + 20..offset + 22].try_into().unwrap()) as usize;
            let entries = u32::from_le_bytes(
                data[offset + value + 16..offset + value + 20]
                    .try_into()
                    .unwrap(),
            ) as usize;
            break offset + value + 16 + entries + 16;
        }
        offset += u32::from_le_bytes(data[offset + 4..offset + 8].try_into().unwrap()) as usize;
    };
    assert!(target + 4 < data.len());
    assert!((target as u64 % sector) < sector - 4);
    file.seek(SeekFrom::Start(location + target as u64))
        .unwrap();
    file.write_all(&0xfffffffeu32.to_le_bytes()).unwrap();
    file.sync_all().unwrap();
    let error = Volume::open(Arc::new(RawDisk::open(&copy).unwrap()))
        .err()
        .expect("must reject mismatched SII/SDS");
    assert_eq!(error.kind(), std::io::ErrorKind::InvalidData, "{error:?}");
    assert!(error.to_string().contains("$SII"));
}

#[test]
#[ignore = "requires independent mkntfs fixture generator"]
fn caller_tightened_metadata_cache_attribute_and_work_limits_reject_real_ntfs() {
    use virtdisk::ParserLimits;
    let directory = tempfile::tempdir().unwrap();
    let image = directory.path().join("limits.ntfs");
    fs::File::create(&image)
        .unwrap()
        .set_len(32 * 1024 * 1024)
        .unwrap();
    command("mkntfs", &["-F", "-Q", image.to_str().unwrap()]);
    let before = fs::read(&image).unwrap();
    let cases = [
        (
            "metadata",
            ParserLimits {
                metadata_bytes: 1,
                ..Default::default()
            },
        ),
        (
            "cache",
            ParserLimits {
                cache_bytes: 1,
                ..Default::default()
            },
        ),
        (
            "attribute",
            ParserLimits {
                attribute_bytes: 1,
                ..Default::default()
            },
        ),
        (
            "work",
            ParserLimits {
                work_items: 1,
                ..Default::default()
            },
        ),
    ];
    for (name, limits) in cases {
        let error = Volume::open_with_limits(Arc::new(RawDisk::open(&image).unwrap()), limits)
            .err()
            .expect(name);
        assert_eq!(
            error.kind(),
            std::io::ErrorKind::Unsupported,
            "{name}: {error}"
        );
        assert!(error.to_string().contains(name), "{name}: {error}");
        assert!(error.get_ref().unwrap().is::<virtdisk::ReadError>());
    }
    let budget = virtdisk::ReadBudget::new(ParserLimits::default()).unwrap();
    budget
        .metadata(budget.limits().metadata_bytes - 512)
        .unwrap();
    let error = Volume::open_with_limits(
        budget.reader(Arc::new(RawDisk::open(&image).unwrap())),
        budget.limits(),
    )
    .err()
    .unwrap();
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(error.to_string().contains("metadata"));
    for work_items in [2, 8, 32, 128] {
        let result = Volume::open_with_limits(
            Arc::new(RawDisk::open(&image).unwrap()),
            ParserLimits {
                work_items,
                ..Default::default()
            },
        )
        .and_then(|volume| volume.capture_manifest());
        if let Err(error) = result {
            assert_eq!(
                error.kind(),
                std::io::ErrorKind::Unsupported,
                "work {work_items}: {error}"
            );
            assert!(error.to_string().contains("work"), "{error}");
        }
    }
    let volume = Volume::open(Arc::new(RawDisk::open(&image).unwrap())).unwrap();
    assert!(volume.capture_manifest().is_ok());
    assert_eq!(fs::read(image).unwrap(), before);
}

#[test]
#[ignore = "requires retained independently formatted nested NTFS fixture; set NTFS_NESTED_FIXTURE"]
fn caller_tightened_depth_rejects_a_real_directory_subtree_without_modifying_volume() {
    use virtdisk::ParserLimits;
    let image = std::env::var_os("NTFS_NESTED_FIXTURE").expect("NTFS_NESTED_FIXTURE");
    let image = std::path::PathBuf::from(image);
    let before = digest(&image);
    let volume = Volume::open(Arc::new(RawDisk::open(&image).unwrap())).unwrap();
    let manifest = volume.capture_manifest().unwrap();
    assert!(
        manifest
            .nodes
            .iter()
            .any(|n| n.parent.is_some_and(|p| manifest.nodes[p].parent.is_some()))
    );
    let volume = Volume::open_with_limits(
        Arc::new(RawDisk::open(&image).unwrap()),
        ParserLimits {
            recursion_depth: 1,
            ..Default::default()
        },
    )
    .unwrap();
    let error = volume.capture_manifest().err().unwrap();
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(error.to_string().contains("recursion"));
    assert!(error.get_ref().unwrap().is::<virtdisk::ReadError>());
    assert_eq!(digest(&image), before);
}

#[test]
#[ignore = "requires detached Windows-created VHD with OddFixture/many-ads.bin; set NTFS_ATTRIBUTE_LIST_FIXTURE"]
fn caller_tightened_attribute_list_limit_rejects_windows_extension_records() {
    use partmgr::partition::PartitionTable;
    use virtdisk::ParserLimits;
    let image = std::path::PathBuf::from(
        std::env::var_os("NTFS_ATTRIBUTE_LIST_FIXTURE").expect("NTFS_ATTRIBUTE_LIST_FIXTURE"),
    );
    let before = digest(&image);
    let table = PartitionTable::read(Arc::new(RawDisk::open(&image).unwrap()), 512).unwrap();
    let volume = Volume::open(Arc::new(table.select(1).unwrap())).unwrap();
    let path = vec![
        "OddFixture".encode_utf16().collect(),
        "many-ads.bin".encode_utf16().collect(),
    ];
    let data = volume
        .read_file(&path, &"stream-159".encode_utf16().collect::<Vec<_>>())
        .unwrap();
    let mut byte = [0];
    data.read_exact_at(0, &mut byte).unwrap();
    assert_eq!(byte, [159]);
    for work_items in [32, 64, 128, 256, 512, 1024] {
        let result = Volume::open_with_limits(
            Arc::new(table.select(1).unwrap()),
            ParserLimits {
                work_items,
                ..Default::default()
            },
        )
        .and_then(|volume| volume.read_file(&path, &[]));
        if let Err(error) = result {
            assert_eq!(
                error.kind(),
                std::io::ErrorKind::Unsupported,
                "work {work_items}: {error}"
            );
            assert!(error.to_string().contains("work"));
        }
    }
    let volume = Volume::open_with_limits(
        Arc::new(table.select(1).unwrap()),
        ParserLimits {
            attribute_list_records: 1,
            ..Default::default()
        },
    )
    .unwrap();
    let error = volume.read_file(&path, &[]).err().unwrap();
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(error.to_string().contains("ATTRIBUTE_LIST"));
    let context = &error
        .get_ref()
        .unwrap()
        .downcast_ref::<virtdisk::ReadError>()
        .unwrap()
        .context;
    assert_eq!(context.partition, Some(1));
    assert_eq!(context.path.as_ref(), Some(&path));
    assert_eq!(digest(&image), before);
}

#[test]
#[ignore = "requires detached Windows-created fixed VHD; set NTFS_ATTRIBUTE_LIST_FIXTURE"]
fn oversized_index_record_is_rejected_before_native_index_allocation() {
    use partmgr::partition::PartitionTable;
    let image = std::path::PathBuf::from(
        std::env::var_os("NTFS_ATTRIBUTE_LIST_FIXTURE").expect("NTFS_ATTRIBUTE_LIST_FIXTURE"),
    );
    let before = digest(&image);
    let source = Arc::new(RawDisk::open(&image).unwrap());
    let table = PartitionTable::read(source.clone(), 512).unwrap();
    let partition = table.partitions().iter().find(|p| p.index == 1).unwrap();
    let base = partition.first_lba * 512;
    let mut bytes = fs::read(&image).unwrap();
    let boot = &bytes[base as usize..base as usize + 512];
    let sector = u16::from_le_bytes(boot[11..13].try_into().unwrap()) as usize;
    let cluster = sector as u64 * u64::from(boot[13]);
    let mft = u64::from_le_bytes(boot[48..56].try_into().unwrap()) * cluster;
    let encoded = boot[64] as i8;
    let record_size = if encoded < 0 {
        1usize << encoded.unsigned_abs()
    } else {
        cluster as usize * encoded as usize
    };
    let start = (base + mft) as usize + 5 * record_size;
    assert_eq!(&bytes[start..start + 4], b"FILE");
    let mut offset = u16::from_le_bytes(bytes[start + 20..start + 22].try_into().unwrap()) as usize;
    loop {
        let ty = u32::from_le_bytes(
            bytes[start + offset..start + offset + 4]
                .try_into()
                .unwrap(),
        );
        assert_ne!(ty, u32::MAX, "independent Windows root lacks INDEX_ROOT");
        let size = u32::from_le_bytes(
            bytes[start + offset + 4..start + offset + 8]
                .try_into()
                .unwrap(),
        ) as usize;
        if ty == 0x90 {
            assert_eq!(bytes[start + offset + 8], 0, "resident INDEX_ROOT required");
            let value = u16::from_le_bytes(
                bytes[start + offset + 20..start + offset + 22]
                    .try_into()
                    .unwrap(),
            ) as usize;
            let field = offset + value + 8;
            assert!(
                field % sector + 4 <= sector - 2,
                "fixture field overlaps USA trailer"
            );
            bytes[start + field..start + field + 4].copy_from_slice(&0x7fff0000u32.to_le_bytes());
            break;
        }
        assert!(size >= 24 && offset + size <= record_size);
        offset += size;
    }
    let directory = tempfile::tempdir().unwrap();
    let copy = directory.path().join("oversized-index.vhd");
    fs::write(&copy, bytes).unwrap();
    let copy_before = digest(&copy);
    let table = PartitionTable::read(Arc::new(RawDisk::open(&copy).unwrap()), 512).unwrap();
    let volume = Volume::open(Arc::new(table.select(1).unwrap())).unwrap();
    let error = volume.capture_manifest().err().unwrap();
    assert_eq!(error.kind(), std::io::ErrorKind::Unsupported);
    assert!(error.to_string().contains("INDEX_ROOT allocation record"));
    assert!(error.to_string().contains("attribute=0x90"), "{error}");
    assert_eq!(digest(&image), before);
    assert_eq!(digest(&copy), copy_before);
}
